func ptrAccountingBackfill(p unsafe.Pointer, c int32) any {
	r := (*accountingbackfill.AccountingBackfill)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ConnectionID))
	case 4:
		return &r.RangeStart
	case 5:
		return &r.RangeEnd
	case 6:
		return (*[]string)(unsafe.Pointer(&r.ObjectTypes))
	case 7:
		return &r.Cursor
	case 8:
		return (*string)(unsafe.Pointer(&r.Status))
	case 9:
		return (*int64)(unsafe.Pointer(&r.EnqueuedCount))
	case 10:
		return (*int64)(unsafe.Pointer(&r.AlreadyQueuedCount))
	case 11:
		return (*string)(unsafe.Pointer(&r.RequestedByID))
	case 12:
		return &r.StartedAt
	case 13:
		return &r.CompletedAt
	case 14:
		return &r.LastError
	case 15:
		return &r.Version
	case 16:
		return &r.CreatedAt
	case 17:
		return &r.UpdatedAt
	}
	return nil
}

func valueAccountingBackfill(p unsafe.Pointer, c int32) any {
	r := (*accountingbackfill.AccountingBackfill)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.ConnectionID)
	case 4:
		return r.RangeStart
	case 5:
		return r.RangeEnd
	case 6:
		if r.ObjectTypes == nil {
			return []string{}
		}
		return keel.Strings(r.ObjectTypes)
	case 7:
		return r.Cursor
	case 8:
		return string(r.Status)
	case 9:
		return int64(r.EnqueuedCount)
	case 10:
		return int64(r.AlreadyQueuedCount)
	case 11:
		if r.RequestedByID == "" {
			return nil
		}
		return string(r.RequestedByID)
	case 12:
		if r.StartedAt == nil {
			return nil
		}
		return *r.StartedAt
	case 13:
		if r.CompletedAt == nil {
			return nil
		}
		return *r.CompletedAt
	case 14:
		if r.LastError == "" {
			return nil
		}
		return r.LastError
	case 15:
		return r.Version
	case 16:
		return r.CreatedAt
	case 17:
		return r.UpdatedAt
	}
	return nil
}

